svg.script:
// A deck is the 52 (suit, rank) pairs minus whichever of its cards are
// lying on the table. Drawing deals a real single_poker_card stamped with
// this deck's id; a card going back to the deck just leaves the table (see
// single_poker_card.return_to_deck), so the deck never has to touch a
// card's DOM, nor a card the deck's.
var poker_deck = {

  SUIT_COUNT: 4,
  RANK_COUNT: 13,
  MAX_DRAW:   5,

  menu: {
    'Draw': {
      eventName: 'poker_deck_draw',
      applicable: (node) => poker_deck._remaining(node).length > 0,
      handler: function(evt, { num } = {}) {
        poker_deck._draw(this, num ?? 1)
      },
      uiLabel: (node) => `Draw (${poker_deck._remaining(node).length})`,
      radial: (node) => ({
        'How many': { param: 'num', type: 'integer', default: 1, min: 1,
                      max: Math.max(1, Math.min(poker_deck.MAX_DRAW, poker_deck._remaining(node).length)) },
      }),
    },
    'Reshuffle': {
      eventName: 'poker_deck_reshuffle',
      applicable: (node) => poker_deck._cards_out(node).length > 0,
      handler: function(evt) {
        poker_deck._collect(this)
      },
      radial: true,
    },
  },

  // Every card on the table (loose, or inside a pile or other container)
  // dealt from this deck.
  _cards_out: function(elem) {
    const layer = elem.closest('#toys-layer')
    const deckId = elem.getAttribute('data-id')
    if (!layer) return []
    return [...layer.querySelectorAll('[data-toy-type="single_poker_card"]')]
      .filter(card => card.getAttribute('data-home-deck') === deckId)
  },

  // [{ suit, rank }] still in the deck.
  _remaining: function(elem) {
    const out = new Set(poker_deck._cards_out(elem).map(c => `${c.dataset.suit}.${c.dataset.rank}`))
    const left = []
    for (let suit = 1; suit <= poker_deck.SUIT_COUNT; suit++) {
      for (let rank = 1; rank <= poker_deck.RANK_COUNT; rank++) {
        if (!out.has(`${suit}.${rank}`)) left.push({ suit, rank })
      }
    }
    return left
  },

  // Deals num random cards, face down, fanned out to the right of the deck.
  _draw: function(elem, num) {
    const left = poker_deck._remaining(elem)
    const deckId = elem.getAttribute('data-id')
    const color = elem.getAttribute('data-color') || undefined
    const svg = elem.querySelector(':scope > svg')
    const x = parseFloat(svg?.getAttribute('x')) || 0
    const y = parseFloat(svg?.getAttribute('y')) || 0
    const w = parseFloat(svg?.getAttribute('width')) || 0
    const h = parseFloat(svg?.getAttribute('height')) || 0

    const count = Math.min(num, left.length)
    for (let i = 0; i < count; i++) {
      const pick = left.splice(Math.floor(Math.random() * left.length), 1)[0]
      poker_deck._event('toy:add', {
        toyType: 'single_poker_card',
        x: x + w + 60 + 20 * i,
        y: y + h / 2,
        color,
        initArgs: { color, suit: pick.suit, rank: pick.rank, deck: deckId },
      })
    }
  },

  _collect: function(elem) {
    poker_deck._cards_out(elem).forEach(card => {
      poker_deck._event('toy:delete', { id: card.getAttribute('data-id') })
    })
  },

  _event: function(evName, args) {
    const detail = { ...args, retval: {} };
    document.dispatchEvent(new CustomEvent(evName, { detail }));
    if (detail.error) throw new Error(detail.error);
    return detail.retval;
  },

}
